import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Card } from '../Card.js';
import { MemoryDrillMode } from '../../constants/memoryDrillModes.js';
import { useLocalStorageState } from '../../hooks/useLocalStorageState.js';
import { useBatchOperations } from '../../hooks/useBatchOperations.js';
import { useQuestionGenerator } from '../../hooks/useQuestionGenerator.js';

const ALL_PREFIXES = Array.from({ length: 32 }, (_, i) => i + 1);

function MemoryDrillGame({ category, onAnswerSubmit }) {
  const initialState = {
    currentMode: null,
    successCount: 0,
    startTime: null,
    responseTime: null,
    instructionsRead: {},
    penaltySettings: {
      enabled: true,
      amount: 1,
      maxAmount: 5
    },
    learnedItems: {
      [MemoryDrillMode.PREFIX_TO_HEXTET]: [],
      [MemoryDrillMode.HEX_TO_BINARY]: [],
      [MemoryDrillMode.BINARY_TO_DECIMAL]: [],
      [MemoryDrillMode.BINARY_TO_HEX]: [],
      [MemoryDrillMode.IPV4_BINARY_TO_DECIMAL]: []
    },
    itemSuccessCounts: {
      [MemoryDrillMode.PREFIX_TO_HEXTET]: {},
      [MemoryDrillMode.HEX_TO_BINARY]: {},
      [MemoryDrillMode.BINARY_TO_DECIMAL]: {},
      [MemoryDrillMode.BINARY_TO_HEX]: {},
      [MemoryDrillMode.IPV4_BINARY_TO_DECIMAL]: {}
    }
  };

  const [drillState, setDrillState] = useLocalStorageState(
    `memory-drill-${category}`,
    initialState
  );
  
  const [selectedPrefixes, setSelectedPrefixes] = useState(() => {
    const saved = localStorage.getItem('memory-drill-selected-prefixes');
    return saved ? JSON.parse(saved) : ALL_PREFIXES.slice(0, 4);
  });
  
  const [currentQuestion, setCurrentQuestion] = useState(null);
  const [input, setInput] = useState('');
  const [result, setResult] = useState(null);
  const [startTime, setStartTime] = useState(null);
  const inputRef = useRef(null);

  const questionGenerator = useQuestionGenerator(
    MemoryDrillMode.PREFIX_TO_HEXTET,
    drillState,
    selectedPrefixes
  );
  
  const { addLearnedItem } = useBatchOperations(drillState, setDrillState);

  useEffect(() => {
    if (!drillState.currentMode) {
      setDrillState(prev => ({ ...prev, currentMode: MemoryDrillMode.PREFIX_TO_HEXTET }));
    }
  }, [drillState.currentMode, setDrillState]);

  useEffect(() => {
    if (drillState.currentMode) {
      const question = questionGenerator();
      setCurrentQuestion(question);
      setStartTime(Date.now());
      setTimeout(() => {
        inputRef.current?.focus();
      }, 10);
    }
  }, [drillState.currentMode, questionGenerator]);

  const submit = useCallback(() => {
    if (!input.trim() || !currentQuestion) return;
    
    const responseTime = Date.now() - startTime;
    const userAnswer = input.trim().toUpperCase();
    const isCorrect = userAnswer === currentQuestion.answer.toUpperCase();
    
    setResult({
      success: isCorrect,
      expected: currentQuestion.answer,
      responseTime,
      question: currentQuestion.question,
      explanation: currentQuestion.explanation,
      userAnswer,
      itemId: currentQuestion.itemId
    });
    
    onAnswerSubmit(category, isCorrect);
    
    if (isCorrect) {
      addLearnedItem(currentQuestion.itemId);
      const newSuccessCount = drillState.successCount + 1;
      setDrillState(prev => ({ ...prev, successCount: newSuccessCount }));
    } else {
      const penaltyAmount = drillState.penaltySettings.enabled
        ? drillState.penaltySettings.amount
        : 0;
      const newSuccessCount = Math.max(0, drillState.successCount - penaltyAmount);
      setDrillState(prev => ({ ...prev, successCount: newSuccessCount }));
    }
    
    setInput('');
  }, [input, startTime, currentQuestion, category, onAnswerSubmit, drillState, addLearnedItem, setDrillState]);

  const next = useCallback(() => {
    const newQuestion = questionGenerator();
    setCurrentQuestion(newQuestion);
    setResult(null);
    setInput('');
    setStartTime(Date.now());
    setTimeout(() => {
      inputRef.current?.focus();
    }, 10);
  }, [questionGenerator]);

  const handleInputChange = useCallback((value) => {
    // Simple validation for prefix mode
    if (/^\d{0,2}$/.test(value) && (value === '' || parseInt(value) <= 31)) {
      setInput(value);
    }
  }, []);

  if (!currentQuestion) {
    return (
      <Card title="Memory Drill - Loading...">
        <div className="text-center">
          <div className="spinner-border" role="status">
            <span className="visually-hidden">Loading...</span>
          </div>
        </div>
      </Card>
    );
  }

  return (
    <Card title="Memory Drill - Prefix → Hextet">
      <div className="mb-3">
        <div className="d-flex justify-content-between align-items-center mb-2">
          <span className="badge bg-primary">
            {selectedPrefixes.length} prefixes selected
          </span>
          <span className="badge bg-info">
            Success Count: {drillState.successCount}
          </span>
        </div>
        <small className="text-muted">
          Practice converting prefix lengths to hextet positions
        </small>
      </div>

      <div className="mb-3">
        <div className="p-4 bg-body-secondary border rounded text-center">
          <div className="mb-2 text-muted small">Question:</div>
          <div className="display-4 font-monospace">{currentQuestion.question}</div>
          <div className="mt-2 text-muted small">
            Which hextet position? (÷4 = ?)
          </div>
        </div>
      </div>

      <div className="mb-3">
        <label className="form-label">Your Answer</label>
        <input
          ref={inputRef}
          type="text"
          className="form-control form-control-lg font-monospace text-center"
          value={input}
          onChange={(e) => handleInputChange(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') {
              if (!result) {
                submit();
              } else {
                next();
              }
            }
          }}
          placeholder="0-31"
          autoComplete="off"
          spellCheck="false"
          disabled={!!result}
        />
        <div className="form-text">
          Enter the integer result of dividing the prefix by 4 (0-31)
        </div>
      </div>

      {result && (
        <div className={`alert ${result.success ? 'alert-success' : 'alert-danger'} mb-3`}>
          <div className="fw-bold mb-1">
            {result.success ? 'Correct!' : 'Incorrect'}
          </div>
          <div className="small">
            {result.explanation}
            {result.success ? (
              <div className="mt-1">
                Response time: {(result.responseTime / 1000).toFixed(2)}s
              </div>
            ) : (
              <div className="mt-1">
                <strong>
                  Penalty applied: Success count reduced by {drillState.penaltySettings.amount}
                </strong>
              </div>
            )}
          </div>
        </div>
      )}

      <div className="d-grid gap-2 mb-3">
        {!result ? (
          <button
            className="btn btn-primary"
            onClick={submit}
            disabled={!input.trim()}
          >
            Submit Answer
          </button>
        ) : (
          <button className="btn btn-success" onClick={next}>
            Next Question
          </button>
        )}
      </div>
    </Card>
  );
}

export default MemoryDrillGame;